### The Industrial Bus Diagnostic Sketch

Here is a complete, production-grade bus scanner sketch with formatted hexadecimal reporting and automatic peripheral identification:

```cpp
#include <Wire.h>

void setup() {
  Wire.begin();
  Serial.begin(9600);
  while (!Serial); // Wait for Serial Monitor connection

  Serial.println("\n==============================================");
  Serial.println("   MONSTER LAB - I2C HARDWARE BUS SCANNER     ");
  Serial.println("==============================================");
}

void loop() {
  byte error, address;
  int nDevices = 0;

  Serial.println("Scanning I2C 7-bit address space (0x01 to 0x7E)...");

  for (address = 1; address < 127; address++) {
    // Transmit to target address with Write bit (0)
    Wire.beginTransmission(address);
    error = Wire.endTransmission();

    if (error == 0) {
      Serial.print(" [!] Device found at address 0x");
      if (address < 16) Serial.print('0');
      Serial.print(address, HEX);
      Serial.print(" (Dec: ");
      Serial.print(address);
      Serial.print(") - ");

      // Identify common Monster Lab components
      if (address == 0x27 || address == 0x3F) {
        Serial.println("16x2 Character LCD Backpack (PCF8574)");
      } else if (address == 0x68) {
        Serial.println("DS3231 Precision Real-Time Clock");
      } else if (address == 0x57) {
        Serial.println("AT24C32 I2C EEPROM (on RTC module)");
      } else {
        Serial.println("Unknown Smart Peripheral");
      }
      nDevices++;
    } else if (error == 4) {
      Serial.print(" [X] Hardware bus error at address 0x");
      if (address < 16) Serial.print('0');
      Serial.println(address, HEX);
    }
  }

  if (nDevices == 0) {
    Serial.println("\nNo I2C devices found! Check power, ground, and SDA/SCL.");
  } else {
    Serial.print("\nScan complete. Total active devices: ");
    Serial.println(nDevices);
  }

  Serial.println("Rescanning in 5 seconds...\n");
  delay(5000);
}
```

### Code Deconstruction:
- `Wire.beginTransmission(address)`: Formats the 8-bit frame: `(address << 1) | 0`.
- `Wire.endTransmission()`: Transmits the frame and listens for the 9th clock ACK pulse.
- `Serial.print(address, HEX)`: Formats the numeric address into standard hex notation with leading zero padding for numbers less than 16.

